'use client';

import React from 'react';
import {
  LayoutDashboard,
  ClipboardCheck,
  HelpCircle,
  Layers,
  AlertCircle,
  Download,
  Settings,
  HelpCircle as HelpIcon,
  ChevronDown,
  ShieldCheck,
} from 'lucide-react';
import type { NavItem } from '@/types/claimtrail';

interface AppSidebarProps {
  currentNav: NavItem | 'overview';
  onNavChange: (nav: NavItem | 'overview') => void;
}

const NAV_ITEMS = [
  { id: 'overview' as const, label: 'Overview', icon: LayoutDashboard },
  { id: 'review' as const, label: 'Review', icon: ClipboardCheck },
  { id: 'questions' as const, label: 'Questions', icon: HelpCircle },
  { id: 'evidence' as const, label: 'Evidence', icon: Layers },
  { id: 'findings' as const, label: 'Findings', icon: AlertCircle },
  { id: 'exports' as const, label: 'Exports', icon: Download },
];

export function AppSidebar({ currentNav, onNavChange }: AppSidebarProps) {
  return (
    <aside className="w-[195px] shrink-0 bg-surface border-r border-border flex flex-col h-full select-none overflow-hidden">
      {/* Brand */}
      <div className="h-[52px] flex items-center px-5 border-b border-border shrink-0">
        <div className="flex items-center gap-2.5">
          <div className="w-7 h-7 rounded bg-text-primary flex items-center justify-center">
            <ShieldCheck className="w-4 h-4 text-accent" />
          </div>
          <span className="font-semibold text-sm text-text-primary tracking-tight">ClaimTrail</span>
        </div>
      </div>

      {/* Primary Navigation */}
      <nav className="flex-1 overflow-y-auto py-3 px-3">
        <ul className="space-y-0.5">
          {NAV_ITEMS.map(({ id, label, icon: Icon }) => {
            const isActive = currentNav === id;
            return (
              <li key={id}>
                <button
                  onClick={() => onNavChange(id as NavItem | 'overview')}
                  className={`w-full flex items-center gap-2.5 px-3 py-2 rounded text-sm transition-colors text-left ${
                    isActive
                      ? 'bg-nav-active-bg text-nav-active-text font-medium'
                      : 'text-nav-text hover:bg-canvas hover:text-text-primary'
                  }`}
                >
                  <Icon
                    className={`w-4 h-4 shrink-0 ${
                      isActive ? 'text-accent' : 'text-text-tertiary'
                    }`}
                  />
                  <span className="truncate">{label}</span>
                </button>
              </li>
            );
          })}
        </ul>

        {/* Workspace section */}
        <div className="mt-6 mb-1 px-3">
          <p className="text-2xs font-semibold uppercase tracking-wider text-text-tertiary">Workspace</p>
        </div>
        <div className="px-3 py-2 rounded border border-border bg-canvas">
          <p className="text-xs font-medium text-text-primary truncate">Acme Corp</p>
          <p className="text-2xs text-text-tertiary mt-0.5 truncate">SOC 2 Type II — 2026</p>
        </div>
      </nav>

      {/* Bottom nav */}
      <div className="shrink-0 border-t border-border py-2 px-3">
        <button className="w-full flex items-center gap-2.5 px-3 py-2 rounded text-sm text-nav-text hover:bg-canvas hover:text-text-primary transition-colors">
          <Settings className="w-4 h-4 shrink-0 text-text-tertiary" />
          <span>Settings</span>
          <ChevronDown className="w-3 h-3 ml-auto text-text-tertiary" />
        </button>
        <button className="w-full flex items-center gap-2.5 px-3 py-2 rounded text-sm text-nav-text hover:bg-canvas hover:text-text-primary transition-colors">
          <HelpIcon className="w-4 h-4 shrink-0 text-text-tertiary" />
          <span>Help Center</span>
          <ChevronDown className="w-3 h-3 ml-auto text-text-tertiary" />
        </button>
      </div>
    </aside>
  );
}
