'use client';

import React from 'react';
import { Search, Bell, Play, RotateCw } from 'lucide-react';

interface AppTopBarProps {
  breadcrumb: string[];
  searchQuery: string;
  onSearchChange: (q: string) => void;
  alertCount: number;
  isRunningCheck: boolean;
  onRunEvidenceCheck: () => void;
  showRunButton?: boolean;
}

export function AppTopBar({
  breadcrumb,
  searchQuery,
  onSearchChange,
  alertCount,
  isRunningCheck,
  onRunEvidenceCheck,
  showRunButton = true,
}: AppTopBarProps) {
  return (
    <header className="h-[52px] shrink-0 bg-surface border-b border-border flex items-center px-5 gap-4 select-none z-20">
      {/* Breadcrumb */}
      <div className="flex items-center gap-1.5 text-sm text-text-secondary min-w-0">
        {breadcrumb.map((crumb, i) => (
          <React.Fragment key={i}>
            {i > 0 && <span className="text-text-tertiary">›</span>}
            <span
              className={
                i === breadcrumb.length - 1
                  ? 'text-text-primary font-medium'
                  : 'text-text-secondary hover:text-text-primary cursor-pointer transition-colors'
              }
            >
              {crumb}
            </span>
          </React.Fragment>
        ))}
      </div>

      {/* Spacer */}
      <div className="flex-1" />

      {/* Search */}
      <div className="relative w-48 lg:w-60">
        <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-text-tertiary pointer-events-none" />
        <input
          type="text"
          placeholder="Search..."
          value={searchQuery}
          onChange={(e) => onSearchChange(e.target.value)}
          className="w-full h-8 pl-8 pr-3 text-sm bg-canvas border border-border rounded placeholder:text-text-tertiary text-text-primary focus:outline-none focus:border-accent focus:ring-1 focus:ring-accent/20 transition-all"
        />
      </div>

      {/* Alert bell — only render if there are real alerts */}
      {alertCount > 0 && (
        <button
          className="relative w-8 h-8 flex items-center justify-center rounded border border-border bg-surface hover:bg-canvas transition-colors"
          title={`${alertCount} active conflicts`}
        >
          <Bell className="w-4 h-4 text-text-secondary" />
          <span className="absolute -top-1 -right-1 w-4 h-4 bg-accent rounded-full flex items-center justify-center text-white text-2xs font-bold leading-none">
            {alertCount}
          </span>
        </button>
      )}

      {/* Primary Action */}
      {showRunButton && (
        <button
          onClick={onRunEvidenceCheck}
          disabled={isRunningCheck}
          className="h-8 px-4 rounded bg-accent hover:bg-accent-hover text-white text-sm font-medium flex items-center gap-2 transition-colors disabled:opacity-60 disabled:cursor-not-allowed shrink-0"
        >
          {isRunningCheck ? (
            <>
              <RotateCw className="w-3.5 h-3.5 animate-spin" />
              <span className="hidden sm:inline">Checking…</span>
            </>
          ) : (
            <>
              <Play className="w-3.5 h-3.5 fill-white" />
              <span>Run Evidence Check</span>
            </>
          )}
        </button>
      )}
    </header>
  );
}
